import{_ as t,o as e,c as i,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-28（生物医学 / 抗病毒 / 刺突抑制剂）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-28-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-28-biomed.md"}'),s={name:"topics/biomedicine/science-daily-2026-10-28-biomed.md"};function r(c,o,d,a,l,g){return e(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-28-生物医学-抗病毒-刺突抑制剂" tabindex="-1">科学日报 · 2026-10-28（生物医学 / 抗病毒 / 刺突抑制剂） <a class="header-anchor" href="#科学日报-·-2026-10-28-生物医学-抗病毒-刺突抑制剂" aria-label="Permalink to &quot;科学日报 · 2026-10-28（生物医学 / 抗病毒 / 刺突抑制剂）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> — 第47期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-28-小分子「三聚」锁死刺突——s22-抑制所有后续奥密克戎变异株" tabindex="-1">科学日报 2026-10-28：小分子「三聚」锁死刺突——S22 抑制所有后续奥密克戎变异株 <a class="header-anchor" href="#科学日报-2026-10-28-小分子「三聚」锁死刺突——s22-抑制所有后续奥密克戎变异株" aria-label="Permalink to &quot;科学日报 2026-10-28：小分子「三聚」锁死刺突——S22 抑制所有后续奥密克戎变异株&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-28.md</code> ｜ DOI: 10.1038/s41467-026-78835-9 ｜ Nature Communications (2026)</p></blockquote><ul><li>问题：SARS-CoV-2 靠<strong>刺突蛋白结合 ACE2</strong> 入侵细胞，而结合的前提是三个<strong>受体结合域（RBD）<strong>中至少一个翻到 <strong>「up」构象</strong>。要找一种</strong>能对所有后续变异株有效</strong>的入侵抑制剂。</li><li>本工作：报道小分子 <strong>S22</strong>——<strong>高效、可生物利用、无毒</strong>的入侵抑制剂，对 <strong>BA.2 及其后全部奥密克戎变异株</strong>有效。</li><li>结果： <ul><li><strong>冷冻电镜</strong>：S22 组装成<strong>三聚体</strong>，卡进<strong>刺突顶端中央腔隙</strong>，把<strong>三个 RBD 全部稳定在「down」构象</strong>，从而阻断 ACE2 结合；</li><li>结合实验（尤其用对 S22 <strong>敏感/耐受混合</strong>的刺突）提示<strong>三个 S22 分子与三个 RBD 协同组装</strong>，导致<strong>异常缓慢的解离速率（off-rate）</strong>；</li><li>凭借慢解离 + 良好药代动力学，S22 在感染 <strong>XBB.1.5</strong> 的雌性小鼠肺中<strong>压制病毒复制与炎症</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code>）： <ol><li><strong>「协同组装 → 慢解离」把「亚化学计量的小分子」变成有效抑制剂</strong> —— 单分子结合通常 off-rate 快、药效弱；三分子协同把三个 RBD 一起锁在 down 构象，off-rate 变慢，等效于「提高驻留时间」。可迁移判据：<strong>当小分子单体亲和力不够时，先问它能否靠「多价/协同组装」把多个靶点同时锁定——价态与协同可以补偿单点亲和力。</strong></li><li><strong>「锁死构象」是一条不同于抗体/蛋白酶抑制剂的机制</strong> —— 抗体靠结合位点、蛋白酶抑制剂靠堵活性中心，S22 靠<strong>把蛋白稳定在非活性构象</strong>（构象锁定）。判据：<strong>当靶点没有明显「口袋」可堵时，改问「能不能把它稳定在一个失活的构象」。</strong></li><li><strong>「对后续全部变异株有效」的来源是「结合保守的中央腔 + 构象依赖」</strong> —— 变异多发生在 RBD 表面（抗体/ACE2 界面），而刺突顶端<strong>中央腔</strong>相对保守，且机制依赖的是<strong>构象态</strong>而非某几个残基。判据：<strong>想设计抗变异逃逸的抑制剂，优先选「保守位点」+「机制依赖构象而非序列」的策略。</strong></li><li><strong>注意措辞克制</strong>：证据是<strong>结构解析 + 体外结合 + 小鼠模型</strong>（XBB.1.5），<strong>尚未进入人体临床</strong>；落库保留「候选抑制剂/临床前」而非「已上市药物」。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第47期 科学板块</p></blockquote><p>关键词：科学日报第47期、SARS-CoV-2 入侵抑制剂、S22、刺突蛋白 spike、受体结合域 RBD、up/down 构象、ACE2、冷冻电镜 cryo-EM、三聚协同组装、中央腔隙、慢解离 off-rate、XBB.1.5 小鼠、奥密克戎 BA.2 及后续变异株、构象锁定、多价协同补偿单点亲和力、保守位点抗逃逸、临床前候选</p><p>关联：<code>topics/biomedicine/index.md</code>、<code>topics/biomedicine/science-daily-2026-10-27-biomed.md</code>（ctDNA/THBS1）、<code>topics/earth-science/index.md</code>、<code>topics/ai-brain/index.md</code></p>',10)])])}const u=t(s,[["render",r]]);export{p as __pageData,u as default};
